// src/components/SignUp.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

const SignUp = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleSignUp = (e) => {
    e.preventDefault();
    // Here you would handle the account creation logic, e.g., API call to create the user.
    // After successfully creating the account:
    navigate("/login-merchant"); // Redirect to login page after signing up
  };

  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold">Create an Account</h1>
      <form onSubmit={handleSignUp}>
        <input
          type="email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          placeholder="Email"
          className="border p-2 m-2"
        />
        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Password"
          className="border p-2 m-2"
        />
        <button type="submit" className="bg-blue-500 text-white p-2 m-2">
          Sign Up
        </button>
      </form>
    </div>
  );
};

export default SignUp;
